#!/usr/bin/env python3
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
matrix_path = ROOT / "data/isa/cpu_architecture_matrix.json"
out = ROOT / "kernel/generated/cpu_arch_registry.generated.h"
data = json.loads(matrix_path.read_text(encoding="utf-8"))
rows = data.get("rows", [])
if len(rows) != data.get("architecture_inventory_count") or not rows:
    raise SystemExit("CPU architecture matrix count mismatch")
ids = [r.get("id") for r in rows]
if len(ids) != len(set(ids)) or any(not isinstance(x, str) or not x for x in ids):
    raise SystemExit("CPU architecture matrix has missing or duplicate identifiers")
runtime = {"x86-64": 1, "x86-32": 4, "aarch64": 2, "arm32": 6, "arm32-thumb": 6, "riscv32": 5, "riscv64": 3}
def target_kind(r):
    return 1 if r.get("target_kind") == "CPU/MCU/DSP ISA" else 2 if r.get("target_kind") == "non-CPU execution ISA" else 0
def detect(r):
    if r["id"] in ("x86-64", "x86-32"): return 2
    if r["id"] in ("aarch64", "arm32", "arm32-thumb", "riscv32", "riscv64"): return 1
    return 0
lines = [
    "/* Generated by tools/isa/generate_cpu_arch_registry.py; do not edit. */",
    "#pragma once", "#include <stdint.h>",
    f"#define KORONOS_CPU_ARCH_REGISTRY_COUNT {len(rows)}u",
    "static const koronos_cpu_arch_descriptor koronos_cpu_arch_registry[] = {"
]
for r in rows:
    native = 1 if r.get("koronos", {}).get("build_target") == "current native x86_64 kernel build" else 0
    lines.append(f'    {{"{r["id"]}", "{r["class"]}", {int(r["word_bits"])}u, {target_kind(r)}u, {runtime.get(r["id"], 0)}u, {native}u, {detect(r)}u}},')
lines += ["};", ""]
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(lines), encoding="utf-8")
print(f"Generated {len(rows)} CPU architecture descriptors: {out}")
